import { ApolloClient, InMemoryCache, createHttpLink, ApolloLink, from } from '@apollo/client';
import { onError } from '@apollo/client/link/error';
import { setContext } from '@apollo/client/link/context';
import { Observable } from '@apollo/client/utilities';
import { refreshToken } from './services/auth';

// Constants for rate limiting
const MAX_RETRIES = 3;
const INITIAL_RETRY_DELAY = 1000; // 1 second
const RATE_LIMIT_DELAY = 2000; // 2 seconds

// Simple retry mechanism for rate limiting
const retryLink = new ApolloLink((operation, forward) => {
  const { retryCount = 0 } = operation.getContext();

  return new Observable(observer => {
    let sub;
    let retrySub;
    let retryCountValue = retryCount;

    const processRequest = () => {
      sub = forward(operation).subscribe({
        next: (result) => {
          if (retryCountValue > 0) {
            console.log(`Request succeeded after ${retryCountValue} retries`);
          }
          observer.next(result);
          observer.complete();
        },
        error: async (error) => {
          const networkError = error.networkError || {};
          const statusCode = error.statusCode || networkError.statusCode;
          const headers = networkError.response?.headers || {};

          // Check for rate limit headers or 429 status
          const rateLimitRemaining = parseInt(headers.get?.('x-ratelimit-remaining') || '1', 10);
          const rateLimitReset = parseInt(headers.get?.('x-ratelimit-reset') || '0', 10) * 1000; // Convert to ms
          const isRateLimited = statusCode === 429 || rateLimitRemaining <= 0;

          if (isRateLimited && retryCountValue < MAX_RETRIES) {
            // Calculate delay with exponential backoff and jitter
            const baseDelay = Math.min(
              RATE_LIMIT_DELAY * Math.pow(2, retryCountValue),
              30000 // Max 30 seconds delay
            );
            const jitter = Math.random() * 1000; // Add up to 1s jitter
            const delay = Math.max(rateLimitReset - Date.now(), baseDelay) + jitter;

            console.warn(`Rate limited. Retrying in ${Math.round(delay/1000)}s... (Attempt ${retryCountValue + 1}/${MAX_RETRIES})`);

            // Wait for the delay and retry
            setTimeout(() => {
              operation.setContext({
                ...operation.getContext(),
                retryCount: retryCountValue + 1
              });

              // Create a new subscription for the retry
              retrySub = processRequest();
            }, delay);

            return;
          }

          // If we shouldn't retry or have exceeded max retries
          if (isRateLimited) {
            const resetTime = new Date(rateLimitReset).toLocaleTimeString();
            observer.error(new Error(`Rate limit exceeded. Please try again after ${resetTime} or contact support.`));
          } else {
            observer.error(error);
          }
        },
        complete: () => observer.complete()
      });

      return sub;
    };

    const subscription = processRequest();

    return () => {
      if (sub) sub.unsubscribe();
      if (retrySub) retrySub.unsubscribe();
      if (subscription) subscription.unsubscribe();
    };
  });
});

// HTTP connection to the API with credentials
const httpLink = createHttpLink({
  uri: 'http://localhost:8000/graphql',
  credentials: 'include' // Include cookies with the request
});

// Middleware to add auth token to headers
const authLink = setContext((_, { headers }) => {
  // Get the authentication token from local storage
  const token = localStorage.getItem('access_token');

  // Return the context with the authorization header
  return {
    headers: {
      ...headers,
      authorization: token ? `Bearer ${token}` : '',
    },
  };
});

// Error handling for authentication
const errorLink = onError(({ graphQLErrors, networkError, operation, forward }) => {
  if (graphQLErrors) {
    for (let err of graphQLErrors) {
      console.error('GraphQL Error:', err);

      // Handle token expiration or invalid token
      if (err.extensions?.code === 'UNAUTHENTICATED' || 
          err.message.includes('Not authenticated') ||
          err.message.includes('Invalid token') ||
          err.message.includes('Token expired')) {

        // Only attempt refresh if this isn't a refresh token request to avoid loops
        if (operation.operationName === 'RefreshToken') {
          console.log('Refresh token request failed, redirecting to login');
          clearAuthAndRedirect();
          return;
        }

        // Try to refresh the token
        const refreshTokenValue = localStorage.getItem('refresh_token');
        if (refreshTokenValue) {
          console.log('Attempting to refresh access token...');
          return refreshToken()
            .then(({ access_token, refresh_token }) => {
              if (!access_token) {
                throw new Error('No access token in refresh response');
              }

              console.log('Token refreshed successfully');

              // Update tokens in storage
              localStorage.setItem('access_token', access_token);
              if (refresh_token) {
                localStorage.setItem('refresh_token', refresh_token);
              }

              // Update the authorization header with the new token
              const oldHeaders = operation.getContext().headers;
              operation.setContext({
                headers: {
                  ...oldHeaders,
                  authorization: `Bearer ${access_token}`,
                },
              });

              // Retry the request with the new token
              return forward(operation);
            })
            .catch(error => {
              console.error('Failed to refresh token:', error);
              clearAuthAndRedirect();
              return;
            });
        } else {
          console.log('No refresh token available, redirecting to login');
          clearAuthAndRedirect();
          return;
        }
      }
    }
  }

  if (networkError) {
    console.error('[Network error]:', networkError);

    // Handle 401 Unauthorized
    if (networkError.statusCode === 401) {
      console.log('Received 401 Unauthorized, clearing auth and redirecting');
      clearAuthAndRedirect();
    }
  }
});

// Helper function to clear auth and redirect to login
function clearAuthAndRedirect() {
  // Clear tokens from localStorage
  localStorage.removeItem('access_token');
  localStorage.removeItem('refresh_token');

  // Clear all cookies by setting their expiration to the past
  document.cookie.split(';').forEach(c => {
    document.cookie = c.trim().split('=')[0] + '=;expires=Thu, 01 Jan 1970 00:00:00 UTC;path=/;';
  });

  // Redirect to login page
  window.location.href = '/login';
}

// Create the Apollo Client instance with cache configuration
const client = new ApolloClient({
  link: from([
    errorLink,
    authLink,
    retryLink.concat(httpLink),
  ]),
  cache: new InMemoryCache({
    typePolicies: {
      Query: {
        fields: {
          // Add any specific field policies here if needed
        },
      },
    },
  }),
  defaultOptions: {
    watchQuery: {
      fetchPolicy: 'network-only',
      errorPolicy: 'all',
    },
    query: {
      fetchPolicy: 'network-only',
      errorPolicy: 'all',
    },
    mutate: {
      errorPolicy: 'all',
    },
  },
});

// Export the client
export default client;
